SELECT sub0.time AS "time", (sub0.value - lag(sub0.value) OVER (ORDER BY sub0.time)) AS "sensor.ENERGY.Total" FROM (SELECT time_bucket('1h', "time", 'Europe/Berlin') AS "time", first("sensor.ENERGY.Total", "time") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > '2025-12-31T23:00:00Z' AND "time" < '2026-01-08T00:00:00Z' GROUP BY 1 ORDER BY 1 ASC LIMIT 170) sub0 ORDER BY 1 DESC LIMIT 168